create table if not exists cosmos_payments(id uuid primary key,payment_id varchar(128) not null unique,fingerprint char(64) not null unique,nonce varchar(128) not null,network varchar(120) not null,chain_id varchar(100) not null,signer varchar(120) not null,recipient varchar(160) not null,denom varchar(160) not null,amount numeric(78,0) not null,transfer_type varchar(16) not null,tx_hash varchar(160),status varchar(24) not null check(status in('settling','broadcast','settled','failed','reverted')),error varchar(500),agent_id uuid,sequence bigint not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(network,signer,nonce));
create table if not exists cosmos_agent_policies(id uuid primary key,agent_id uuid not null references agents(id) on delete cascade,enabled boolean not null default true,allowed_networks text[] not null,allowed_recipients text[] not null,allowed_denoms text[] not null,allowed_fee_granters text[] not null default '{}',allowed_ibc_channels text[] not null default '{}',max_per_payment numeric(78,0) not null,daily_budget numeric(78,0) not null,monthly_budget numeric(78,0) not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists cosmos_budget_idx on cosmos_payments(agent_id,status,created_at);
insert into schema_migrations(version) values('012_cosmos') on conflict do nothing;
